INSERT INTO `activity_logs` VALUES (453, NULL, NULL, 'CREATE_KPI', '{\"id\":\"kpi_1786501078899633\",\"name\":\"F1.1 Net Interst Margin (NIM)\",\"perspective\":\"financial\",\"unit\":\"percentage\",\"target\":\"0\",\"actual\":\"0.00\",\"weight\":\"10.00\",\"unit_name\":\"Divisi Perencanaan Strategis\",\"jabatan\":\"Pj.Pemimpin Divisi Perencanaan Strategis\",\"strategy_id\":null,\"manual_indeks\":null,\"monthly_data\":{},\"monthly_target\":null,\"unit_type\":\"divisi\",\"parent_kpi_id\":null,\"status\":\"on_track\",\"description\":\"Rasio profitabilitas perbankan yang mengukur kemampuan bank menghasilkan laba dari selisih bunga yang diterima dari pinjaman (pendapatan bunga) dan bunga yang dibayar untuk dana pihak ketiga (beban bunga), dibandingkan dengan total aset produktifnya. Semakin tinggi NIM, semakin efisien bank dalam mengelola asetnya untuk mendapatkan keuntungan bersih dari aktivitas utamanya, yaitu meminjam dan meminjamkan uang\",\"formula\":null,\"objective\":\"F1. Peningkatan Pendapatan Operasional\",\"approved_by\":null,\"approved_at\":null,\"created_by\":null,\"updated_by\":null,\"created_at\":\"2026-08-12T02:17:58.000Z\",\"is_locked\":0,\"sort_order\":0,\"params\":{},\"query\":{},\"body\":{\"name\":\"F1.1 Net Interst Margin (NIM)\",\"unit\":\"percentage\",\"weight\":10,\"target\":0,\"perspective\":\"financial\",\"actual\":0,\"status\":\"on_track\",\"jabatan\":\"Pj.Pemimpin Divisi Perencanaan Strategis\",\"unit_type\":\"divisi\",\"unit_name\":\"Divisi Perencanaan Strategis\",\"monthly_data\":{},\"monthly_target\":{},\"objective\":\"F1. Peningkatan Pendapatan Operasional\",\"description\":\"Rasio profitabilitas perbankan yang mengukur kemampuan bank menghasilkan laba dari selisih bunga yang diterima dari pinjaman (pendapatan bunga) dan bunga yang dibayar untuk dana pihak ketiga (beban bunga), dibandingkan dengan total aset produktifnya. Semakin tinggi NIM, semakin efisien bank dalam mengelola asetnya untuk mendapatkan keuntungan bersih dari aktivitas utamanya, yaitu meminjam dan meminjamkan uang\",\"formula\":\"\"}}', '2026-08-12 09:17:58', 'superadmin', '140.213.36.174');
