INSERT INTO `strategies` VALUES ('str_1777342792809', 'obj_1777342617562', 'Kerugian Akibat Non-Complience', 'financial', '%', 'Mengukur besaran kerugian finansial akibat ketidakpatuhan terhadap regulasi/kebijakan internal dibanding total pendapatan.', 'Kerugian akibat non-compliance / Total Pendapatan Operasional × 100%', 10.00, '≤ 0,50');
INSERT INTO `strategies` VALUES ('str_1777342853504', 'obj_1777342644384', 'Tingkat Kesehatan Bank', 'customer', 'Indeks (TK-1 s.d TK-5)', 'Penilaian kesehatan bank berbasis RBBR (Risk Profile, GCG, Earnings, Capital).', 'Hasil self-assessment RBBR', 10.00, 'Komposit 2 (Sehat)');
INSERT INTO `strategies` VALUES ('str_1777342890842', 'obj_1777342633886', 'Kerugian Akibat Denda Dari regulator', 'financial', '%', 'Mengukur dampak finansial dari sanksi/denda regulator terhadap kinerja bank.', 'Total Denda Regulator / Total Pendapatan Operasional × 100%', 5.00, '≤ 0,10');
INSERT INTO `strategies` VALUES ('str_1777342919143', 'obj_1777342655846', 'Nilai Indeks Kepatuhan dari OJK', 'customer', 'Indeks', 'Penilaian tingkat kepatuhan bank terhadap ketentuan regulator.', 'Nilai evaluasi kepatuhan dari OJK / Regulator terkait', 10.00, '≥ 90 (Sangat Baik)');
INSERT INTO `strategies` VALUES ('str_1777342959524', 'obj_1777342664670', 'SLA Pengujian /Opini Kepatuhan', 'internal_process', 'Hari Kerja', 'Waktu penyelesaian proses review/pengujian kepatuhan sejak dokumen lengkap diterima.', 'Tanggal selesai – Tanggal diterima lengkap', 5.00, '≤ 5 hari kerja');
INSERT INTO `strategies` VALUES ('str_1777342996109', 'obj_1777342664670', 'Skor Tata Kelola (Skor GCG)', 'internal_process', 'Indeks', 'Skor implementasi Good Corporate Governance.', 'Hasil self-assessment GCG', 10.00, '≥ 90');
INSERT INTO `strategies` VALUES ('str_1777343036074', 'obj_1777342664670', 'Skor Kepatuhan', 'internal_process', 'Indeks', 'Tingkat kepatuhan terhadap kebijakan internal dan regulasi eksternal.', '(Jumlah kepatuhan terpenuhi / total kewajiban kepatuhan) × 100', 5.00, '≥ 90');
INSERT INTO `strategies` VALUES ('str_1777343092619', 'obj_1777342675204', 'Jumlah Fraud yang ditemukan dalam tahun berjalan', 'internal_process', 'Kasus', 'Jumlah kejadian fraud yang terdeteksi dalam periode berjalan.', 'Total kasus fraud terverifikasi', 10.00, '≤ 3 kasus/tahun (atau menurun YoY)');
INSERT INTO `strategies` VALUES ('str_1777343161951', 'obj_1777342685108', 'Realisasi Program Kerja RBB Divisi Sesuai Timeline', 'internal_process', 'percentage', 'Tingkat pencapaian program kerja sesuai rencana bisnis bank.', 'Realisasi program / rencana × 100%', 5.00, '≥ 95%');
INSERT INTO `strategies` VALUES ('str_1777343194480', 'obj_1777342695413', 'Penyelesaian Tindak Lanjut Temuan', 'internal_process', 'percentage', 'Tingkat penyelesaian tindak lanjut atas temuan audit/regulator.', 'Temuan selesai / total temuan × 100%', 5.00, '≥ 95%');
INSERT INTO `strategies` VALUES ('str_1777343216516', 'obj_1777342705426', 'Culture Implementation Index', 'learning_growth', 'Indeks', '≥ 95%', 'Cakupan penilaian risiko industri pada portofolio kredit di seluruh unit.', 5.00, '0.05');
INSERT INTO `strategies` VALUES ('str_1777343237638', 'obj_1777342716143', 'Digital Skill Index', 'learning_growth', 'Indeks', '1', 'Tingkat penyelesaian pengembangan model credit scoring.', 5.00, '0.05');
INSERT INTO `strategies` VALUES ('str_1777432406659', 'obj_1777427044834', 'Cost Saving Audit', 'financial', '%', 'Total nilai penghematan biaya (cost saving) yang dihasilkan dari implementasi rekomendasi audit internal yang telah disetujui dan direalisasikan oleh manajemen. Cost saving mencakup: Efisiensi biaya operasional (overhead, proses, vendor), Pengurangan pemborosan (inefficiency elimination), Optimasi proses bisnis, Renegosiasi kontrak/vendor, Pengurangan biaya akibat kontrol yang tidak efektif.', '(Realisasi Cost Saving​/Target Cost Saving) x 100%', 10.00, '≥ Rp XX miliar / tahun (nominal absolut) Atau ≥ 5% dari total biaya operasional yang diaudit');
INSERT INTO `strategies` VALUES ('str_1777432457475', 'obj_1777427067043', 'Potensi Kerugian Yang Teridentifikasi dari Audit', 'financial', 'Rp', 'Total nilai potensi kerugian yang berhasil diidentifikasi oleh audit sebelum terjadi realisasi kerugian', '((Potensi Kerugian Tahun Berjalan - Tahun Lalu) / Tahun )) x 100 %', 10.00, '≥ 10% YoY growth dari potensi kerugian yang teridentifikasi');
INSERT INTO `strategies` VALUES ('str_1777432486144', 'obj_1777427081774', 'Recovery Kerugian Akibat Fraud', 'financial', 'Rp', 'Persentaase nilai kerugian fraud yang berhasil dipulihkan dibandingkan total kerugian fraud', '(Total Recovery Fraud/Total Kerugian Fraud) x 100%', 5.00, '> 90 % Kerugian');
INSERT INTO `strategies` VALUES ('str_1777432539672', 'obj_1777427167352', 'Realisasi Program Kerja RBB Divisi Sesuai Timeline', 'internal_process', '%', 'Persentase realisasi program kerja audit dibandingkan rencana tahunan (RBB)', '(Program Audit Selesai Tepat Waktu/Totatal Program Audit) x 100%', 5.00, '100 %');
INSERT INTO `strategies` VALUES ('str_1777432586871', 'obj_1777427179144', 'Penyelesaian Tindak Lanjut Temuan', 'internal_process', '%', 'Persentase temuan audit yang telah ditindaklanjuti dan ditutup', '(Temuan Closed​/Total Temuan) x 100%', 5.00, '≥ 90');
INSERT INTO `strategies` VALUES ('str_1777432608676', 'obj_1777427192501', 'Follow-up Completion Rate', 'internal_process', '%', 'Memastikan tindak lanjut temuan diselesaikan tepat waktu', '(Temuan Closed ≤ SLA/Total Temuan) x 100%', 5.00, '≥ 95');
INSERT INTO `strategies` VALUES ('str_1777432634640', 'obj_1777427204282', 'High Risk Finding Identified', 'internal_process', '%', 'Persentase temuan dengan kategori high risk dari total temuan', '(Temuan High Risk​/Total Temuan) x 100%', 5.00, '≥ 20% dari total temuan');
INSERT INTO `strategies` VALUES ('str_1777432667839', 'obj_1777427215387', 'Risk-Based Audit Coverage', 'internal_process', '%', 'Fraud Terdeteksi oleh Audit / Total Fraud', '(Unit High Risk yang Diaudit​/Total Unit High Risk)x 100%', 5.00, '100% high risk area');
INSERT INTO `strategies` VALUES ('str_1777432688841', 'obj_1777427228352', 'Fraud Terdeteksi Dibanding Total Fraud', 'internal_process', '%', 'Persentase kasus fraud yang berhasil dideteksi oleh audit dibandingkan total fraud', '(Fraud Terdeteksi oleh Audit​/Total Fraud) x 100%', 10.00, '>70%');
